// ═══════════════════════════════════════════════
// PHANTOMFX v4.0 — CENTRAL CONFIG
// ═══════════════════════════════════════════════
//
// 🔀 AI_MODE: Pilih salah satu
//    "openclaw"     → Pakai OpenClaw Gateway (GRATIS, ga perlu API key tambahan)
//    "claude"       → Pakai Anthropic Claude API langsung (perlu ANTHROPIC_API_KEY)
//    "openai"       → Pakai OpenAI API langsung (perlu OPENAI_API_KEY)
//
// 📡 Env vars WAJIB:
//    TELEGRAM_BOT_TOKEN   = Token bot @berkahkaryaforexbotbot
//    TELEGRAM_CHAT_ID     = -1002928711742 (AIgo Expert Hub)
//
// 📡 Env vars MODE-SPECIFIC:
//    [openclaw] OPENCLAW_GATEWAY_URL = http://localhost:20128/v1
//    [openclaw] OPENCLAW_API_KEY     = *** OpenClaw
//    [claude]   ANTHROPIC_API_KEY    = sk-ant-...
//    [openai]   OPENAI_API_KEY       = sk-...
//
// 📡 Env vars OPTIONAL (MT5 auto-execute):
//    MT5_ROUTER_URL      = http://localhost:8080
//    MT5_ROUTER_API_KEY  = *** key

const AI_MODE = 'openclaw';  // ← GANTI DISINI: "openclaw" | "claude" | "openai"

const now = new Date();
const hourWIB = (now.getUTCHours() + 7) % 24;

let session, killzoneLondon, killzoneNY;
if (hourWIB >= 9 && hourWIB < 17) {
  session = 'London';
  killzoneLondon = (hourWIB >= 9 && hourWIB < 11);
} else if (hourWIB >= 17 && hourWIB < 19) {
  session = 'Overlap';
} else if (hourWIB >= 19 && hourWIB < 23) {
  session = 'New York';
  killzoneNY = (hourWIB >= 20 && hourWIB < 22);
} else {
  session = 'Asian';
}

// Build AI endpoint based on mode
let aiUrl, aiModel, aiHeaders, aiBodyBuilder;

if (AI_MODE === 'openclaw') {
  aiUrl = (process.env.OPENCLAW_GATEWAY_URL || 'http://localhost:20128') + '/chat/completions';
  aiModel = 'claude-sonnet-4-5';
  aiHeaders = { 'Authorization': 'Bearer ' + (process.env.OPENCLAW_API_KEY || '') };
} else if (AI_MODE === 'claude') {
  aiUrl = 'https://api.anthropic.com/v1/messages';
  aiModel = 'claude-sonnet-4-20250514';
  aiHeaders = {
    'x-api-key': process.env.ANTHROPIC_API_KEY || '',
    'anthropic-version': '2023-06-01'
  };
} else if (AI_MODE === 'openai') {
  aiUrl = 'https://api.openai.com/v1/chat/completions';
  aiModel = 'gpt-4o';
  aiHeaders = { 'Authorization': 'Bearer ' + (process.env.OPENAI_API_KEY || '') };
}

const lossCount = $getWorkflowStaticData('global').loss_count_today || 0;

return {
  timestamp: now.toISOString(), session, hourWIB, killzoneLondon, killzoneNY, lossCount,
  AI_MODE, aiUrl, aiModel, aiHeaders,
  telegramToken: process.env.TELEGRAM_BOT_TOKEN || process.env.PHANTOMFX_TELEGRAM_BOT_TOKEN || '',
  telegramChatId: process.env.TELEGRAM_CHAT_ID || process.env.PHANTOMFX_TELEGRAM_CHAT_ID || '',
  mt5RouterUrl: process.env.MT5_ROUTER_URL || '',
  mt5ApiKey: process.env.MT5_ROUTER_API_KEY || ''
};

const r = $input.all()[0]?.json;
const content = r?.choices?.[0]?.message?.content || r?.content?.[0]?.text || '';

if (!content) return { error: 'Empty AI response', raw: JSON.stringify(r).slice(0,200) };

const jsonMatch = content.match(/```json\s*\n([\s\S]*?)\n```/) || content.match(/\{[^{}]*"system"[^}]*\}/);
let parsed = {};
try { parsed = jsonMatch ? JSON.parse(jsonMatch[1] || jsonMatch[0]) : JSON.parse(content); }
catch(e) { return { error: 'JSON parse failed', raw: content.slice(0,500) }; }

const signalMatch = content.match(/---TELEGRAM_SIGNAL_START---\n([\s\S]*?)\n---TELEGRAM_SIGNAL_END---/);
const killzoneMatch = content.match(/---TELEGRAM_KILLZONE_START---\n([\s\S]*?)\n---TELEGRAM_KILLZONE_END---/);
const circuitMatch = content.match(/---TELEGRAM_CIRCUIT_START---\n([\s\S]*?)\n---TELEGRAM_CIRCUIT_END---/);

return {
  parsed,
  signal: signalMatch ? signalMatch[1] : null,
  killzone: killzoneMatch ? killzoneMatch[1] : null,
  circuit: circuitMatch ? circuitMatch[1] : null
};

const parsed = $input.all()[0]?.json?.parsed || {};
const global = $getWorkflowStaticData('global');

if (parsed.action === 'HOLD' && parsed.reason === 'CIRCUIT_BREAKER_3X_LOSS') {
  global.loss_count_today = Math.min((global.loss_count_today || 0) + 1, 10);
}

const history = global.cycleHistory || [];
history.push({
  timestamp: new Date().toISOString(),
  combat_style: parsed.combat_style || 'N/A',
  action: parsed.action || 'HOLD',
  skc: parsed.skc_score?.total || 0,
  grade: parsed.grade || 'N/A'
});
if (history.length > 500) history.shift();
global.cycleHistory = history;

const hWIB = (new Date().getUTCHours() + 7) % 24;
if (hWIB === 0) global.loss_count_today = 0;

return { lossCount: global.loss_count_today, cycles: history.length };
